36	public class FileTests {
37	
38	    private static String join(String dir, String file) {
39	        if (dir.length() == 0) return file;
40	        else return dir + "/" + file;
41	    }
42	
43	    public static class BaseTest extends TestCase {
44	        /**
45	         * Directory-qualified file name
46	         */
47	        String f;
48	        /**
49	         * Just the directory.
50	         */
51	        String dir;
52	        /**
53	         * The name of the test.
54	         */
55	        String name;
56	        /**
57	         * The search path for analysis, compilation, etc.
58	         */
59	        String path;
60	        
61	        String whoami() {
62	            return getClass().getSimpleName() + " " + f;
63	        }
64	
65	        /**
66	         * If true, only print test output for unexpected results.
67	         */
68	        final boolean unexpectedOnly;
69	        final boolean knownFailure;
70	        final boolean shouldFail;
71	
72	        final boolean printSuccess;
73	        final boolean printFailure;
74	
75	        public BaseTest(String _path,
76	                        String _dir,
77	                        String _name,
78	                        boolean unexpected_only,
79	                        boolean knownFailure,
80	                        boolean shouldFail) {
81	            super("testFile");
82	            this.f = join(_dir, _name);
83	            this.dir = _dir;
84	            this.path = _path;
85	            this.name = _name;
86	            this.unexpectedOnly = unexpected_only;
87	
88	            this.printSuccess = !unexpected_only || knownFailure;
89	            this.printFailure = !unexpected_only || !knownFailure;
90	            this.knownFailure = knownFailure;
91	            this.shouldFail = shouldFail;
92	        }
93	
94	        public String getName() {
95	            return f;
96	        }
97	
98	        /**
99	         * Returns true if this test should be regarded as a "Failure",
100	         * regardless of the XXX test name or not.  This can be used to
101	         * test that a particular exception was thrown, for example; not only
102	         * should (say) XXXbadNumber thrown an exception, it should throw
103	         * a NumberFormatException.  Thus, the exc string could be tested
104	         * to see that it contains "NumberFormatException".
105	         *
106	         * @param out
107	         * @param err
108	         * @param exc
109	         * @return
110	         */
111	        public String testFailed(String out, String err, String exc) {
112	            return null;
113	        }
114	
115	        /**
116	         * Looks for properties of the form
117	         * compile/link/run_
118	         * out/err/exceptions_
119	         * contains/matches/WImatches/equals/WCIequals,
120	         * returns true if an expected condition fails.
121	         *
122	         * @param pfx
123	         * @param props
124	         * @param out
125	         * @param err
126	         * @param exc
127	         * @return
128	         */
129	        protected String generalTestFailed(String pfx, StringMap props, String out, String err, String exc) {
130	            String s = null;
131	
132	            if (s == null) s = generalTestFailed(pfx, props, "out", out);
133	
134	            if (s == null) s = generalTestFailed(pfx, props, "err", err);
135	
136	            if (s == null) s = generalTestFailed(pfx, props, "exception", exc);
137	            return s;
138	
139	        }
140	
141	        private String generalTestFailed(String pfx, StringMap props, String which, String contents) {
142	            String what;
143	            String test;
144	
145	            boolean any_check = false;
146	
147	            what = pfx + which + "_contains";
148	            test = props.get(what);
149	            test = ProjectProperties.get(test);
150	            if (test != null && test.length() > 0) {
151	                if (!contents.contains(test)) return what + "; expected\n" + test;
152	                any_check = true;
153	            }
154	
155	            what = pfx + which + "_does_not_contain";
156	            test = props.get(what);
157	            test = ProjectProperties.get(test);
158	            if (test != null && test.length() > 0) {
159	                if (contents.contains(test)) return what + "; expected\n" + test;
160	                any_check = true;
161	            }
162	
163	            what = pfx + which + "_matches";
164	            test = props.get(what);
165	            test = ProjectProperties.get(test);
166	            if (test != null && test.length() > 0) {
167	                if (!contents.matches(test)) return what + "; expected\n" + test;
168	                any_check = true;
169	            }
170	
171	            what = pfx + which + "_WImatches";
172	            test = props.get(what);
173	            test = ProjectProperties.get(test);
174	            if (test != null && test.length() > 0) {
175	                String wi_contents = contents.replaceAll("\\s+", " ").trim();
176	                if (!wi_contents.matches(test)) return what + "; expected\n" + test;
177	                any_check = true;
178	            }
179	
180	            what = pfx + which + "_WCIequals";
181	            test = props.get(what);
182	            test = props.getCompletely(test);
183	            if (test != null && test.length() > 0) {
184	                String wci_contents = contents.replaceAll("\\s+", " ").trim();
185	                String wci_test = test.replaceAll("\\s+", " ").trim();
186	                if (!wci_contents.equalsIgnoreCase(wci_test)) return what + "; expected\n" + test;
187	                any_check = true;
188	            }
189	
190	            what = pfx + which + "_equals";
191	            test = props.get(what);
192	            test = props.getCompletely(test);
193	            if (test != null && test.length() > 0) {
194	
195	                String wi_contents = contents.replaceAll("[ \\\t]+", " ");
196	                String wi_test = test.replaceAll("[ \\\t]+", " ");
197	                // Convert Windows CRLF to UNIX LF
198	                wi_contents = wi_contents.replaceAll("\\\r\\\n", "\n");
199	                wi_test = wi_test.replaceAll("\\\r\\\n", "\n");
200	                // Convert Mac CR to UNIX LF
201	                wi_contents = wi_contents.replaceAll("\\\r", "\n");
202	                wi_test = wi_test.replaceAll("\\\r", "\n");
203	
204	                if (!wi_contents.equals(wi_test)) {
205	                    if (wi_contents.trim().equals(wi_test.trim())) {
206	                        // It is a leading/trailing whitespace problem....
207	                        char c0 = wi_contents.charAt(0);
208	                        char t0 = wi_test.charAt(0);
209	                        char cN = wi_contents.charAt(wi_contents.length() - 1);
210	                        char tN = wi_test.charAt(wi_test.length() - 1);
211	                        String problem = "";
212	                        if (c0 == ' ' || c0 == '\n') {
213	                            if (t0 == ' ' || t0 == '\n') {
214	
215	                            } else {
216	                                problem += "text began with unexpected whitespace";
217	                            }
218	                        } else {
219	                            if (t0 == ' ' || t0 == '\n') {
220	                                problem += "text began without expected whitespace";
221	                            } else {
222	
223	                            }
224	                        }
225	
226	                        String problemAnd = problem.length() > 0 ? problem + " and " : problem;
227	
228	                        if (cN == ' ' || cN == '\n') {
229	                            if (tN == ' ' || tN == '\n') {
230	
231	                            } else {
232	                                problem = problemAnd + "text ended with unexpected whitespace";
233	                            }
234	                        } else {
235	                            if (tN == ' ' || tN == '\n') {
236	                                problem = problemAnd + "text ended without expected whitespace";
237	                            } else {
238	
239	                            }
240	                        }
241	
242	                        return what + ": " + problem;
243	                    } else if (wi_contents.replaceAll("\\s+", " ").trim().equals(wi_test.replaceAll("\\s+",
244	                                                                                                    " ").trim())) {
245	                        String cL = wi_contents.replaceAll("\n[ \t]+", "\n").trim();
246	                        String cT = wi_contents.replaceAll("[ \t]+\n", "\n").trim();
247	                        String tL = wi_test.replaceAll("\n[ \t]+", "\n").trim();
248	                        String tT = wi_test.replaceAll("[ \t]+\n", "\n").trim();
249	
250	                        if (cL.equals(tL)) return what + ": different LEADING whitespace on some line(s)";
251	
252	                        else if (cT.equals(tT)) return what + ": different TRAILING whitespace on some line(s)";
253	
254	                        else if (wi_contents.replaceAll("[ \\\t]*\\\n[ \\\t]*", "\n").trim().equals(wi_test.replaceAll(
255	                                "[ \\\t]*\\\n[ \\\t]*",
256	                                "\n").trim()))
257	                            return what + ": different LEADING AND TRAILING whitespace on some line(s)";
258	
259	                        return what + ": some sort of an internal whitespace problem (linebreaks?)";
260	                    }
261	                    return what + "; expected\n" + test;
262	                }
263	                any_check = true;
264	            }
265	
266	            if (!any_check && pfx.equals("run_") && which.equals("out")) {
267	                // If there is no check specified on run_out, demand that it
268	                // contain "pass" or "PASS".
269	                if (!(contents.contains("pass") || contents.contains("PASS"))) {
270	                    return "default check run_out_contains=PASS";
271	                }
272	            }
273	
274	            return null;
275	        }
276	
277	    }
278	
279	    /**
280	     * For tests that are applied to a single source file (or are rooted at a
281	     * single source file), this takes care of checking for success/failure,
282	     * what is expected, printing, etc.
283	     */
284	    public abstract static class SourceFileTest extends BaseTest {
285	        public SourceFileTest(String path,
286	                              String d,
287	                              String s,
288	                              boolean unexpected_only,
289	                              boolean knownFailure,
290	                              boolean shouldFail) {
291	            super(path, d, s, unexpected_only, knownFailure, shouldFail);
292	        }
293	
294	        public abstract String tag();
295	
296	        public void testFile() throws Throwable {
297	            // Useful when a test is running forever
298	            //            System.out.println(this.name);
299	            //            System.out.flush();
300	
301	            PrintStream oldOut = System.out;
302	            PrintStream oldErr = System.err;
303	            WireTappedPrintStream wt_err = WireTappedPrintStream.make(System.err, unexpectedOnly);
304	            WireTappedPrintStream wt_out = WireTappedPrintStream.make(System.out, unexpectedOnly);
305	            System.setErr(wt_err);
306	            System.setOut(wt_out);
307	
308	
309	            long start = System.nanoTime();
310	            //String fssFile = f + ".fss";
311	            int rc = 0;
312	
313	            try {
314	                //BufferedReader in = null;
315	                try {
316	                    oldOut.print(" " + tag() + " ");
317	                    oldOut.print(f);
318	                    oldOut.print(" ");
319	                    oldOut.flush();
320	                    //in = Useful.utf8BufferedFileReader(fssFile);
321	
322	                    rc = justTheTest();
323	                }
324	                finally {
325	                    System.setErr(oldErr);
326	                    System.setOut(oldOut);
327	                    //if (in != null)
328	                    //    in.close();
329	                }
330	            }
331	            catch (Throwable ex) {
332	                String outs = wt_out.getString();
333	                String errs = wt_err.getString();
334	                String exFirstLine = ex.toString();
335	                String trueFailure = testFailed(outs, errs, exFirstLine);
336	                if (f.contains("XXX")) {
337	                    if (trueFailure != null) {
338	                        unexpectedExceptionBoilerplate(wt_err, wt_out, ex, " Did not satisfy " + trueFailure);
339	                        return;
340	
341	                    } else {
342	                        // "Failed", but correctly
343	                        // !unexpectedOnly || expectFailure
344	                        wt_err.flush(printSuccess);
345	                        wt_out.flush(printSuccess);
346	                        int crLoc = exFirstLine.indexOf("\n");
347	                        if (crLoc == -1) crLoc = exFirstLine.length();
348	                        exFirstLine = exFirstLine.substring(0, crLoc);
349	                        if (printSuccess) System.out.println(exFirstLine);
350	                        System.out.println(" OK Saw expected exception");
351	                        return;
352	                    }
353	                } else {
354	                    unexpectedExceptionBoilerplate(wt_err, wt_out, ex, " UNEXPECTED exception ");
355	                    // return;
356	                }
357	            }
358	            finally {
359	                //fr.clear();
360	            }
361	
362	            /* Come here IFF NO EXCEPTIONS, to analyze output */
363	
364	            String outs = wt_out.getString();
365	            String errs = wt_err.getString();
366	
367	            boolean anyFails = ! f.contains("QuickCheckTest") &&
368	                               (outs.contains("fail") || outs.contains("FAIL") ||
369	                                errs.contains("fail") || errs.contains("FAIL") ||
370	                                rc != 0);
371	
372	            String trueFailure = testFailed(outs, errs, "");
373	
374	            if (shouldFail) {
375	                // NOTE expect to see this on STANDARD OUTPUT, not ERROR.
376	                if (anyFails && trueFailure == null) {
377	                    wt_err.flush(printSuccess);
378	                    wt_out.flush(printSuccess);
379	                    // Saw a failure, that is good.
380	                    System.out.println(" Saw expected failure");
381	                } else {
382	                    if (printFailure) System.out.println();
383	                    wt_err.flush(printFailure);
384	                    wt_out.flush(printFailure);
385	                    if (trueFailure != null) {
386	                        System.out.println(" Saw failure, but did not satisfy " + trueFailure);
387	                        // Expected exception, saw none.
388	                        fail("Saw wrong failure. " + whoami());
389	                    } else {
390	                        System.out.println(" Missing expected failure ");
391	                        // Expected exception, saw none.
392	                        fail("Expected failure or exception, saw none. " + whoami());
393	                    }
394	                }
395	            } else {
396	                // This logic is a little confusing.
397	                // Failure is failure.  TrueFailure contains the better message.
398	                if (anyFails && trueFailure == null) trueFailure = "FAIL or fail should not appear in output";
399	
400	                long duration = (System.nanoTime() - start) / 1000000;
401	                System.out.println(trueFailure != null ? " FAIL" : " OK (time = " + duration + "ms)");
402	                wt_err.flush(trueFailure != null ? printFailure : printSuccess);
403	                wt_out.flush(trueFailure != null ? printFailure : printSuccess);
404	
405	                assertTrue("Must satisfy " + trueFailure + " " + whoami(), trueFailure == null);
406	
407	            }
408	        }
409	
410	        /**
411	         * @param wt_err
412	         * @param wt_out
413	         * @param ex
414	         * @param s
415	         * @throws IOException
416	         */
417	        private void unexpectedExceptionBoilerplate(WireTappedPrintStream wt_err,
418	                                                    WireTappedPrintStream wt_out,
419	                                                    Throwable ex,
420	                                                    String s) throws IOException {
421	            if (printFailure) System.out.println();
422	            wt_err.flush(printFailure);
423	            wt_out.flush(printFailure);
424	            if (printFailure) {
425	                System.out.println(s);
426	                ex.printStackTrace();
427	                fail(whoami());
428	            } else {
429	                System.out.println(s);
430	                fail(ex.getMessage() + " " + whoami());
431	            }
432	        }
433	
434	        abstract protected int justTheTest() throws FileNotFoundException, IOException, Throwable;
435	
436	    }
437	
438	    public static class TestTest extends BaseTest {
439	
440	        private final StringMap props;
441	
442	        public TestTest(StringMap _props,
443	                        String _path,
444	                        String _dir,
445	                        String _name,
446	                        boolean unexpected_only,
447	                        boolean knownFailure,
448	                        boolean shouldFail) {
449	            super(_path, _dir, _name, unexpected_only, knownFailure, shouldFail);
450	            this.props = _props;
451	        }
452	
