860	     * @param shuffled
861	     * @param dir_name_from_user
862	     * @param dir_name_slashes_normalized
863	     * @param dir_name_canonical
864	     * @param failsOnly
865	     * @param expect_failure
866	     * @return
867	     * @throws IOException
868	     */
869	    public static TestSuite suiteFromListOfFiles(Iterable<String> shuffled,
870	                                                 String dir_name_from_user,
871	                                                 String dir_name_slashes_normalized,
872	                                                 String dir_name_canonical,
873	                                                 boolean failsOnly,
874	                                                 boolean expect_failure) throws IOException {
875	        int testCount = testCount();
876	        int i = testCount;
877	
878	        TestSuite suite = new TestSuite("Runs all tests in " + dir_name_from_user) {
879	            public void run(TestResult result) {
880	                super.run(result);
881	                Init.allowForLeakChecks();
882	            }
883	        };
884	
885	        List<Test> commandTests = new ArrayList<Test>();
886	        List<Test> runTests = new ArrayList<Test>();
887	
888	        for (String s : shuffled) {
889	            int slashi = s.lastIndexOf('/');
890	            if (slashi != -1) {
891	                String candidatedir = s.substring(0, slashi);
892	                s = s.substring(slashi + 1);
893	                //dir_name_from_user = candidatedir;
894	                dir_name_slashes_normalized = candidatedir;
895	                dir_name_canonical = directoryAsFile(dir_name_slashes_normalized).getCanonicalPath();
896	            }
897	
898	
899	            if (i <= 0) {
900	                System.out.println("Early testing exit after " + testCount + " tests");
901	                break;
902	            }
903	            boolean decrement = true;
904	            boolean shouldFail = s.startsWith("XXX");
905	
906	            if (s.endsWith(".fss") || s.endsWith(".fsi")) {
907	                // do nothing
908	                decrement = false;
909	            } else if (!s.startsWith(".")) {
910	                if (s.endsWith(".sh")) {
911	                    int l = s.lastIndexOf(".sh");
912	                    String testname = s.substring(0, l);
913	                    suite.addTest(new ShellTest(dir_name_canonical,
914	                                                dir_name_slashes_normalized,
915	                                                testname,
916	                                                failsOnly,
917	                                                expect_failure));
918	                } else if (s.endsWith(".test")) { // need to define the test of tests.
919	                    String propFileName = join(dir_name_canonical, s);
920	                    StringMap props = new StringMap.FromFileProps(propFileName);
921	                    if (props.isEmpty()) {
922	                        throw new java.io.FileNotFoundException("File not found or empty: "+propFileName);
923	                    }
924	                    props = ProjectProperties.composedWith(props);
925	
926	                    int l = s.lastIndexOf(".test");
927	                    String testname = s.substring(0, l);
928	
929	                    String testNames = props.get("tests");
930	                    if (testNames == null) testNames = "";
931	                    else testNames = testNames.trim();
932	
933	                    if (testNames.length() > 0) {
934	                        StringTokenizer st = new StringTokenizer(testNames);
935	                        while (st.hasMoreTokens()) {
936	                            String token = st.nextToken();
937	                            standardCompilerTests(props,
938	                                                  dir_name_canonical,
939	                                                  dir_name_slashes_normalized,
940	                                                  token,
941	                                                  expect_failure,
942	                                                  shouldFail,
943	                                                  failsOnly,
944	                                                  commandTests,
945	                                                  runTests);
946	                        }
947	                    } else {
948	                        standardCompilerTests(props,
949	                                              dir_name_canonical,
950	                                              dir_name_slashes_normalized,
951	                                              testname,
952	                                              expect_failure,
953	                                              shouldFail,
954	                                              failsOnly,
955	                                              commandTests,
956	                                              runTests);
957	                    }
958	                } else {
959	                    System.out.println("Not compiling file " + s);
960	                    decrement = false;
961	                }
962	            }
963	
964	            if (decrement) {
965	                i--;
966	            }
967	
968	        }
969	        // Do all the larger tests
970	        if (i > 0) {
971	            for (Test test : commandTests) {
972	                suite.addTest(test);
973	            }
974	
975	            for (Test test : runTests) {
976	                suite.addTest(test);
977	            }
978	            
979	            if (! ProjectProperties.getBoolean("fortress.unittests.noopt", false)) {
980	
981	                if (runTests.size() > 0) {
982	                    // Run the bytecode optimizer as a test.
983	                    suite.addTest(new ShellTest(ProjectProperties.FORTRESS_AUTOHOME+"/bin", ProjectProperties.FORTRESS_AUTOHOME+"/bin", "BytecodeOptimizeEverything", failsOnly, expect_failure));
984	                    for (Test test : runTests) {
985	                        if (test instanceof TestTest) {
986	                            suite.addTest(new TestTest(new StringMap.FromPair("run.script", "runOpt"), (TestTest) test));
987	                        }
988	                    }
989	                }
990	            }
991	        }
992	        return suite;
993	    }
