1012	                                              boolean shouldFail,
1013	                                              boolean failsOnly,
1014	                                              List<Test> commandTests,
1015	                                              List<Test> runTests) throws IOException {
1016	        String[] commands = new String[]{
1017	                "compile", "desugar", "link", "api", "parse", "disambiguate", "grammar", "typecheck", "unparse",
1018	                "compare", "build"
1019	        };
1020	        String[] supported = new String[]{"run", "fss", "fsi"};
1021	        boolean found = false;
1022	        for (String c : new ArrayList<String>(java.util.Arrays.asList(commands))) {
1023	            if (props.get(c) != null) {
1024	                commandTests.add(new CommandTest(c,
1025	                                                 props,
1026	                                                 canonicalDirName,
1027	                                                 dirname,
1028	                                                 testname,
1029	                                                 failsOnly,
1030	                                                 expect_not_passing,
1031	                                                 shouldFail));
1032	                found = true;
1033	            }
1034	        }
